export function normalizeClassName(className?: string): string {
  if (!className) return "";
  const c = className.trim();
  if (c.includes("Internasional") || c === "6 INT") return "6 Internasional";
  return c.replace(/\s+/g, " ");
}

export function searchSantri(query: string, limit = 20, scopedClass?: string): SantriData[] {
  let pool = ALL_SANTRI_DATA;
  if (scopedClass && scopedClass !== "all") {
    const norm = normalizeClassName(scopedClass);
    const matched = pool.filter(s => s.kelasLengkap === norm || s.kelasLengkap.toLowerCase() === norm.toLowerCase());
    if (matched.length > 0) {
      pool = matched;
    }
  }

  if (!query || !query.trim()) return pool.slice(0, limit);
  const q = query.toLowerCase().trim();
  return pool.filter(s => 
    s.nama.toLowerCase().includes(q) ||
    s.nis.includes(q) ||
    s.nisn.includes(q) ||
    s.kelasLengkap.toLowerCase().includes(q) ||
    s.kabupaten.toLowerCase().includes(q) ||
    s.asalSekolah.toLowerCase().includes(q) ||
    s.namaAyah.toLowerCase().includes(q) ||
    s.namaIbu.toLowerCase().includes(q)
  ).slice(0, limit);
}

export function getSantriByExactClass(className: string): SantriData[] {
  if (!className || className === "all") return ALL_SANTRI_DATA;
  const norm = normalizeClassName(className);
  return ALL_SANTRI_DATA.filter(s => s.kelasLengkap === norm || s.kelasLengkap.toLowerCase() === norm.toLowerCase());
}

export function getSantriForMusyrif(musyrifKelas?: string, musyrifTingkat?: string): SantriData[] {
  if (!musyrifKelas) return ALL_SANTRI_DATA;
  const norm = normalizeClassName(musyrifKelas);
  
  if (norm.includes("&")) {
    const parts = norm.split("&").map(p => normalizeClassName(p.trim()));
    return ALL_SANTRI_DATA.filter(s => parts.some(p => s.kelasLengkap === p || s.kelasLengkap.includes(p)));
  }

  const direct = ALL_SANTRI_DATA.filter(s => s.kelasLengkap === norm || s.kelasLengkap.toLowerCase() === norm.toLowerCase());
  if (direct.length > 0) return direct;

  return ALL_SANTRI_DATA.filter(s => s.kelasLengkap.toLowerCase().includes(norm.toLowerCase()));
}

export function getSantriStats() {
  const byJenjang = { MTs: 0, MA: 0 };
  const byTingkat: Record<string, number> = {};
  const byKelas: Record<string, number> = {};

  ALL_SANTRI_DATA.forEach(s => {
    if (s.jenjang === "MTs") byJenjang.MTs++;
    else byJenjang.MA++;

    byTingkat[s.tingkat] = (byTingkat[s.tingkat] || 0) + 1;
    byKelas[s.kelasLengkap] = (byKelas[s.kelasLengkap] || 0) + 1;
  });

  return {
    total: ALL_SANTRI_DATA.length,
    byJenjang,
    byTingkat,
    byKelas
  };
}

export function getClassMetadata(kelasName: string): { tingkat: string; tingkatRomawi: string; jenjang: string; paralel: string } {
  const norm = normalizeClassName(kelasName);
  let tingkat = "Kelas 1";
  let tingkatRomawi = "Kelas VII";
  let jenjang = "MTs";
  let paralel = "A";

  if (norm.startsWith("1")) {
    tingkat = "Kelas 1";
    tingkatRomawi = "Kelas VII";
    jenjang = "MTs";
    paralel = norm.replace(/^1\s*/, "");
  } else if (norm.startsWith("2")) {
    tingkat = "Kelas 2";
    tingkatRomawi = "Kelas VIII";
    jenjang = "MTs";
    paralel = norm.replace(/^2\s*/, "");
  } else if (norm.startsWith("3")) {
    tingkat = "Kelas 3";
    tingkatRomawi = "Kelas IX";
    jenjang = "MTs";
    paralel = norm.replace(/^3\s*/, "");
  } else if (norm.startsWith("4")) {
    tingkat = "Kelas 4";
    tingkatRomawi = "Kelas X";
    jenjang = "MA";
    paralel = norm.replace(/^4\s*/, "");
  } else if (norm.startsWith("5")) {
    tingkat = "Kelas 5";
    tingkatRomawi = "Kelas XI";
    jenjang = "MA";
    paralel = norm.replace(/^5\s*/, "");
  } else if (norm.startsWith("6")) {
    tingkat = "Kelas 6";
    tingkatRomawi = "Kelas XII";
    jenjang = "MA";
    paralel = norm.replace(/^6\s*/, "");
  }

  return { tingkat, tingkatRomawi, jenjang, paralel };
}

export interface SiblingInfo {
  santri: SantriData;
  relationship: "kakak" | "adik" | "kembar" | "saudara";
}

/**
 * Builds a fast lookup map for all siblings in the dataset based on parent identity & contact.
 */
export function buildSiblingMap(santriList: SantriData[]): Map<string, SiblingInfo[]> {
  function normalizeString(str?: string) {
    if (!str) return "";
    return str.toLowerCase().replace(/[^a-z0-9]/g, "").trim();
  }

  function normalizePhone(phone?: string) {
    if (!phone) return "";
    let clean = phone.replace(/[^0-9]/g, "");
    if (clean.startsWith("62")) clean = "0" + clean.slice(2);
    return clean.length >= 8 ? clean : "";
  }

  function getGradeNumber(tingkat?: string): number {
    if (!tingkat) return 1;
    const m = tingkat.match(/\d+/);
    return m ? parseInt(m[0], 10) : 1;
  }

  const familyGroups = new Map<string, SantriData[]>();

  santriList.forEach(s => {
    const normAyah = normalizeString(s.namaAyah);
    const normIbu = normalizeString(s.namaIbu);
    const telpAyah = normalizePhone(s.telpAyah);
    const telpIbu = normalizePhone(s.telpIbu);

    let key: string | null = null;
    if (normAyah.length >= 3 && normIbu.length >= 3) {
      key = `parents:${normAyah}_${normIbu}`;
    } else if (telpAyah && telpAyah.length >= 9 && normAyah.length >= 3) {
      key = `phone_ayah:${telpAyah}`;
    } else if (telpIbu && telpIbu.length >= 9 && normIbu.length >= 3) {
      key = `phone_ibu:${telpIbu}`;
    }

    if (key) {
      if (!familyGroups.has(key)) familyGroups.set(key, []);
      familyGroups.get(key)!.push(s);
    }
  });

  const resultMap = new Map<string, SiblingInfo[]>();

  familyGroups.forEach(members => {
    if (members.length > 1) {
      members.forEach(current => {
        const siblings: SiblingInfo[] = [];
        const currentGrade = getGradeNumber(current.tingkat);

        members.forEach(other => {
          if (other.id !== current.id) {
            const otherGrade = getGradeNumber(other.tingkat);
            let rel: "kakak" | "adik" | "kembar" | "saudara" = "saudara";

            if (otherGrade > currentGrade) {
              rel = "kakak";
            } else if (otherGrade < currentGrade) {
              rel = "adik";
            } else {
              // Same grade level
              if (other.tanggalLahir && current.tanggalLahir && other.tanggalLahir === current.tanggalLahir) {
                rel = "kembar";
              } else {
                rel = "saudara";
              }
            }

            siblings.push({ santri: other, relationship: rel });
          }
        });

        // Sort siblings: Kakak first, then Adik
        siblings.sort((a, b) => getGradeNumber(b.santri.tingkat) - getGradeNumber(a.santri.tingkat));
        resultMap.set(current.id, siblings);
      });
    }
  });

  return resultMap;
}

